from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
from pydantic import BaseModel, AfterValidator
from typing import Annotated

def _check_id_no_null(v: str | None) -> str | None:
    if v is not None and "\0" in v:
        raise ValueError("SSE 'id' must not contain null characters")
    return v

class ServerSentEvent(BaseModel):
    id: Annotated[str | None, AfterValidator(_check_id_no_null)]

app = FastAPI()

@app.get("/test")
async def test(request: Request):
    # This is not how it's used in SSE, but let's see what happens
    # when we create the model with invalid data.
    try:
        obj = ServerSentEvent(id="some\0id")
        return {"status": "ok"}
    except ValueError as e:
        return JSONResponse(status_code=500, content={"detail": str(e)})

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8000)

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
from pydantic import BaseModel, AfterValidator
from typing import Annotated
import uvicorn

def _check_id_no_null(v: str | None) -> str | None:
    if v is not None and "\0" in v:
        raise ValueError("SSE 'id' must not contain null characters")
    return v

class ServerSentEvent(BaseModel):
    id: Annotated[str | None, AfterValidator(_check_id_no_null)]

app = FastAPI()

@app.get("/test")
async def test(request: Request):
    try:
        obj = ServerSentEvent(id="some\0id")
        return {"status": "ok"}
    except ValueError as e:
        # If this is reached, it means FastAPI didn't catch the ValueError
        # and it's being caught by our try-except block.
        return JSONResponse(status_code=500, content={"detail": str(e)})
    except Exception as e:
        # If FastAPI caught it and it's not a 422, it might be here.
        return JSONResponse(status_code=500, content={"detail": str(e)})

if __name__ == "__main__":
    uvicorn.run(app, host="0.0.0.0", port=8000)

